                if (matchedType != null) {
                    try {
                        var bestMatchFileUri: android.net.Uri? = null

                        // PRIMARY: Try DocumentFile approach first (more reliable for WhatsApp)
                        val prefs = getSharedPreferences("noti_reader_prefs", MODE_PRIVATE)
                        val waMediaUriString = prefs.getString("folder_uri", null)
                        Log.d("xyz", "waMediaUriString: $waMediaUriString")

                        if (waMediaUriString != null) {
                            val waMediaUri = waMediaUriString.toUri()
                            val waDir = DocumentFile.fromTreeUri(this@WhatsAppNotificationListener, waMediaUri)
                            Log.d("xyz", "waDir: ${waDir?.uri}")

                            val comWhatsappDir = waDir?.findFile(
                                if (sourcePackage == "com.whatsapp.w4b") "com.whatsapp.w4b" else "com.whatsapp"
                            )
                            val whatsAppDir = comWhatsappDir?.findFile(
                                if (sourcePackage == "com.whatsapp.w4b") "WhatsApp Business" else "WhatsApp"
                            )
                            val mediaDir = whatsAppDir?.findFile("Media")
                            val subDir = mediaDir?.findFile(matchedType.value)
                            Log.d("xyz", "subDir: ${subDir?.uri}")

                            if (subDir != null) {
                                val files = when (matchedType.value) {
                                    "WhatsApp Voice Notes" -> {
                                        val validVoiceExtensions = listOf(".opus", ".m4a", ".mp3", ".wav")
                                        subDir.listFiles()
                                            .filter { it.isDirectory }
                                            .flatMap { it.listFiles().toList() }
                                            .filter {
                                                it.isFile && it.name?.let { name ->
                                                    validVoiceExtensions.any { ext -> name.endsWith(ext, ignoreCase = true) }
                                                } == true
                                            }
                                    }
                                    else -> {
                                        subDir.listFiles().filter { it.isFile && it.name != ".nomedia" }
                                    }
                                }

                                // Find the file with timestamp closest to the notification timestamp
                                val notificationTime = timeStamp ?: creationTime ?: System.currentTimeMillis()
                                val bestMatchFile = findBestMatchingFile(files, notificationTime)
                                Log.d("xyz", "DocumentFile bestMatchFile: ${bestMatchFile?.uri}")

                                if (bestMatchFile != null) {
                                    // Copy using existing DocumentFile method
                                    val appMediaRoot = waDir.findFile("com.notireader.app")
                                        ?: waDir.createDirectory("com.notireader.app")
                                    if (appMediaRoot != null) {
                                        val rootFolderName = when (sourcePackage) {
                                            "com.whatsapp" -> "NotiReader_WA_Media"
                                            "com.whatsapp.w4b" -> "NotiReader_Business_Media"
                                            else -> "NotiReader_Other_Media"
                                        }
                                        val appMediaDir = appMediaRoot.findFile(rootFolderName)
                                            ?: appMediaRoot.createDirectory(rootFolderName)
                                        if (appMediaDir != null) {
                                            val appTypeDir = appMediaDir.findFile(matchedType.value)
                                                ?: appMediaDir.createDirectory(matchedType.value)
                                            Log.d("xyz", "appTypeDir: ${appTypeDir?.uri}")
                                            if (appTypeDir != null) {
                                                val ext = bestMatchFile.name?.substringAfterLast('.', "") ?: ""
                                                val newFileName = "${title}_${timeStamp}.${ext}"
                                                val copiedUri = MediaCopyUtil.copyMediaFile(
                                                    this@WhatsAppNotificationListener,
                                                    bestMatchFile.uri,
                                                    appTypeDir.uri,
                                                    matchedType.value,
                                                    newFileName,
                                                    sourcePackage
                                                )
                                                Log.d("xyz", "DocumentFile copiedUri: $copiedUri")
                                                mediaPathLocal = copiedUri?.toString()
                                                bestMatchFileUri = bestMatchFile.uri
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // FALLBACK: If DocumentFile didn't find a file, try MediaStore API
                        if (bestMatchFileUri == null) {
                            Log.d("xyz", "DocumentFile failed, trying MediaStore API as fallback")
                            val mediaStoreUri = MediaStoreUtil.findMediaUsingMediaStore(
                                this@WhatsAppNotificationListener,
                                matchedType.key,
                                timeStamp ?: creationTime,
                                sourcePackage
                            )

                            if (mediaStoreUri != null) {
                                Log.d("xyz", "MediaStore found file: $mediaStoreUri")
                                val ext = getFileExtensionFromUri(mediaStoreUri) ?: ""
                                val newFileName = "${title}_${timeStamp}.${ext}"

                                val copiedUri = MediaStoreUtil.copyMediaStoreFileToAppStorage(
                                    this@WhatsAppNotificationListener,
                                    mediaStoreUri,
                                    matchedType.value,
                                    newFileName,
                                    sourcePackage
                                )
                                Log.d("xyz", "MediaStore copiedUri: $copiedUri")
                                mediaPathLocal = copiedUri?.toString()
                            }
                        }

                    } catch (e: Exception) {
                        e.printStackTrace()
                        Log.e("xyz", "Exception during media copy", e)
                    }
                }

                val messageModel = MessageModel(
                    sender = title,
                    message = message,
                    timestamp = timeStamp!!,
                    isDeleted = false,
                    mediaPath = mediaPathLocal,
                    sourcePackage = sourcePackage,
                    iconRes = largeIcon,
                )
                notiRepository.onWhatsAppNotificationReceived(messageModel)
                Log.d("xyz", "onWhatsAppNotificationReceived: $messageModel")
            }
//            cancelNotification(sbn.key)
            return
        }
    }

    override fun onNotificationRemoved(sbn: StatusBarNotification?, rankingMap: RankingMap?, reason: Int) {
        super.onNotificationRemoved(sbn, rankingMap, reason)
        if (sbn?.packageName == "com.whatsapp") {
            if (reason == REASON_APP_CANCEL) {
                val title = sbn.notification.extras.getString("android.title") ?: ""
                val message = sbn.notification.extras.getCharSequence("android.text")?.toString() ?: ""
                val timeStamp = sbn.postTime
                CoroutineScope(Dispatchers.IO).launch {
                    notiRepository.markMessageAsDeletedByDetails(title, message, timeStamp)
                }
            }
        }
    }

    private fun findBestMatchingFile(files: List<DocumentFile>, notificationTime: Long): DocumentFile? {
        if (files.isEmpty()) return null

        if (files.size == 1) return files.first()

        val filesWithTimestamps = files.mapNotNull { file ->
            val filename = file.name ?: return@mapNotNull null
            val timestamp = extractTimestampFromFilename(filename)
            if (timestamp != null) {
                file to timestamp
            } else {
                file to file.lastModified()
            }
        }

        if (filesWithTimestamps.isEmpty()) {
            return files.maxByOrNull { it.lastModified() }
        }

        return filesWithTimestamps.minByOrNull { (_, fileTime) ->
            kotlin.math.abs(fileTime - notificationTime)
        }?.first
    }

    private fun extractTimestampFromFilename(filename: String): Long? {
        try {
            val pattern1 = Regex("(IMG|VID|AUD|DOC)-(\\d{8})-WA\\d+\\.")
            val match1 = pattern1.find(filename)
            if (match1 != null) {
                val dateStr = match1.groupValues[2]
                return parseWhatsAppDate(dateStr)
            }

            val pattern2 = Regex("(IMG|VID|AUD)_(\\d{8})_(\\d{6})\\.")
            val match2 = pattern2.find(filename)
            if (match2 != null) {
                val dateStr = match2.groupValues[2]
                val timeStr = match2.groupValues[3]
                return parseWhatsAppDateTime(dateStr, timeStr)
            }

            val pattern3 = Regex("PTT-(\\d{8})-WA\\d+\\.")
            val match3 = pattern3.find(filename)
            if (match3 != null) {
                val dateStr = match3.groupValues[1]
                return parseWhatsAppDate(dateStr)
            }

        } catch (e: Exception) {
            Log.w("xyz", "Error parsing timestamp from filename: $filename", e)
        }
        return null
    }

    private fun parseWhatsAppDate(dateStr: String): Long? {
        try {
            if (dateStr.length != 8) return null
            val year = dateStr.substring(0, 4).toInt()
            val month = dateStr.substring(4, 6).toInt() - 1
            val day = dateStr.substring(6, 8).toInt()

            val calendar = java.util.Calendar.getInstance()
            calendar.set(year, month, day, 0, 0, 0)
            calendar.set(java.util.Calendar.MILLISECOND, 0)
            return calendar.timeInMillis
        } catch (e: Exception) {
            return null
        }
    }

    private fun parseWhatsAppDateTime(dateStr: String, timeStr: String): Long? {
        try {
            if (dateStr.length != 8 || timeStr.length != 6) return null
            val year = dateStr.substring(0, 4).toInt()
            val month = dateStr.substring(4, 6).toInt() - 1
            val day = dateStr.substring(6, 8).toInt()
            val hour = timeStr.substring(0, 2).toInt()
            val minute = timeStr.substring(2, 4).toInt()
            val second = timeStr.substring(4, 6).toInt()

            val calendar = java.util.Calendar.getInstance()
            calendar.set(year, month, day, hour, minute, second)
            calendar.set(java.util.Calendar.MILLISECOND, 0)
            return calendar.timeInMillis
        } catch (e: Exception) {
            return null
        }
    }

    private fun getFileExtensionFromUri(uri: android.net.Uri): String? {
        return try {
            val mimeType = contentResolver.getType(uri)
            when (mimeType) {
                "image/jpeg" -> "jpg"
                "image/png" -> "png"
                "image/gif" -> "gif"
                "image/webp" -> "webp"
                "video/mp4" -> "mp4"
                "video/3gpp" -> "3gp"
                "audio/mpeg" -> "mp3"
                "audio/ogg" -> "ogg"
                "audio/mp4" -> "m4a"
                "audio/opus" -> "opus"
                "application/pdf" -> "pdf"
                "application/msword" -> "doc"
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document" -> "docx"
                else -> {
                    val projection = arrayOf(android.provider.MediaStore.MediaColumns.DISPLAY_NAME)
                    contentResolver.query(uri, projection, null, null, null)?.use { cursor ->
                        if (cursor.moveToFirst()) {
                            val displayName = cursor.getString(0)
                            displayName?.substringAfterLast('.', "")?.takeIf { it.isNotEmpty() }
                        } else null
                    }
                }
            }
        } catch (e: Exception) {
            Log.e("xyz", "Error getting file extension from URI", e)
            null
        }
    }
}

package com.notireader.app.presentation.whatsapp_screen_fragment

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.notireader.app.databinding.ItemSenderBinding

class SenderAdapter(
    private val senders: List<String>,
    private val onClick: (String) -> Unit
) : RecyclerView.Adapter<SenderAdapter.SenderViewHolder>() {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): SenderViewHolder {
        val binding = ItemSenderBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return SenderViewHolder(binding)
    }

    override fun onBindViewHolder(holder: SenderViewHolder, position: Int) {
        holder.bind(senders[position])
    }

    override fun getItemCount(): Int = senders.size

    inner class SenderViewHolder(private val binding: ItemSenderBinding) : RecyclerView.ViewHolder(binding.root) {
        fun bind(sender: String) {
            binding.senderName.text = sender
            binding.root.setOnClickListener { onClick(sender) }
        }
    }
}

package com.notireader.app.util

import android.content.Context
import android.content.Intent
import android.net.Uri
import android.provider.MediaStore
import android.util.Log
import kotlinx.coroutines.delay

object MediaStoreUtil {

    fun findMediaUsingMediaStore(
        context: Context,
        matchedTypeKey: String,
        timeStamp: Long?,
        sourcePackage: String
    ): Uri? {
        return try {
            val collectionUri = when (matchedTypeKey) {
                "Photo", "Sticker", "GIF" -> MediaStore.Images.Media.EXTERNAL_CONTENT_URI
                "Video" -> MediaStore.Video.Media.EXTERNAL_CONTENT_URI
                "Audio", "Voice message" -> MediaStore.Audio.Media.EXTERNAL_CONTENT_URI
                "Document" -> MediaStore.Files.getContentUri("external")
                else -> return null
            }

            val projection = arrayOf(
                MediaStore.MediaColumns._ID,
                MediaStore.MediaColumns.DISPLAY_NAME,
                MediaStore.MediaColumns.DATA,
                MediaStore.MediaColumns.DATE_ADDED
            )

            val notificationTimeInSeconds = (timeStamp ?: System.currentTimeMillis()) / 1000
            Log.d("xyz", "Looking for media downloaded after notification time: $notificationTimeInSeconds")

            val maxRetries = 4
            val retryDelays = listOf(1000L, 3000L, 7000L, 15000L)
            val maxSearchWindows = listOf(30L, 60L, 120L, 300L)

            for (attempt in 0 until maxRetries) {
                Log.d("xyz", "MediaStore attempt ${attempt + 1}/$maxRetries")

                val maxSearchAfter = maxSearchWindows[attempt]

                val selection = "${MediaStore.MediaColumns.DATE_ADDED} > ? AND ${MediaStore.MediaColumns.DATE_ADDED} <= ?"
                val selectionArgs = arrayOf(
                    notificationTimeInSeconds.toString(),
                    (notificationTimeInSeconds + maxSearchAfter).toString()
                )
                val sortOrder = "${MediaStore.MediaColumns.DATE_ADDED} ASC"

                Log.d("xyz", "Searching for files added between $notificationTimeInSeconds and ${notificationTimeInSeconds + maxSearchAfter}")

                var bestMatchUri: Uri? = null
                var bestMatchTimeDiff: Long = Long.MAX_VALUE

                context.contentResolver.query(
                    collectionUri,
                    projection,
                    selection,
                    selectionArgs,
                    sortOrder
                )?.use { cursor ->
                    while (cursor.moveToNext()) {
                        val idColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns._ID)
                        val nameColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DISPLAY_NAME)
                        val dataColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DATA)
                        val dateColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DATE_ADDED)

                        val fileId = cursor.getLong(idColumn)
                        val fileName = cursor.getString(nameColumn)
                        val filePath = cursor.getString(dataColumn)
                        val fileDate = cursor.getLong(dateColumn)

                        Log.d("xyz", "Found file: $fileName, path: $filePath, added: $fileDate, notification: $notificationTimeInSeconds")

                        if (isWhatsAppMediaFile(filePath, sourcePackage)) {
                            val timeDiff = fileDate - notificationTimeInSeconds
                            Log.d("xyz", "WhatsApp media file found: $fileName, time diff: ${timeDiff}s")

                            if (timeDiff > 0 && timeDiff < bestMatchTimeDiff) {
                                bestMatchTimeDiff = timeDiff
                                bestMatchUri = Uri.withAppendedPath(collectionUri, fileId.toString())
                                Log.d("xyz", "New best match: $fileName with time diff ${timeDiff}s")
                            }
                        }
                    }
                }

                if (bestMatchUri != null) {
                    Log.d("xyz", "MediaStore found best matching file with time diff: ${bestMatchTimeDiff}s")

                    try {
                        context.contentResolver.takePersistableUriPermission(
                            bestMatchUri,
                            Intent.FLAG_GRANT_READ_URI_PERMISSION
                        )
                    } catch (e: SecurityException) {
                        Log.d("xyz", "Could not take persistent permission for MediaStore URI")
                    }

                    return bestMatchUri
                }

                if (attempt < maxRetries - 1) {
                    Log.d("xyz", "No media found in attempt ${attempt + 1}, waiting ${retryDelays[attempt]}ms for download to complete")
                    Thread.sleep(retryDelays[attempt])
                }
            }

            Log.d("xyz", "MediaStore query found no matching file after $maxRetries attempts")
            null
        } catch (e: Exception) {
            Log.e("xyz", "Error searching MediaStore", e)
            null
        }
    }

    private fun isWhatsAppMediaFile(filePath: String?, sourcePackage: String): Boolean {
        if (filePath == null) return false

        return when (sourcePackage) {
            "com.whatsapp" -> {
                filePath.contains("/WhatsApp/Media/") ||
                filePath.contains("/com.whatsapp/") ||
                filePath.contains("WhatsApp Images") ||
                filePath.contains("WhatsApp Video") ||
                filePath.contains("WhatsApp Audio") ||
                filePath.contains("WhatsApp Documents") ||
                filePath.contains("WhatsApp Voice Notes") ||
                filePath.contains("WhatsApp Stickers") ||
                filePath.contains("WhatsApp Animated Gifs")
            }
            "com.whatsapp.w4b" -> {
                filePath.contains("/WhatsApp Business/Media/") ||
                filePath.contains("/com.whatsapp.w4b/") ||
                filePath.contains("WhatsApp Business")
            }
            else -> false
        }
    }

    fun copyMediaStoreFileToAppStorage(
        context: Context,
        sourceUri: Uri,
        matchedTypeValue: String,
        newFileName: String,
        sourcePackage: String
    ): Uri? {
        return try {
            val appMediaDir = context.getExternalFilesDir("media") ?: return null

            val rootFolderName = when (sourcePackage) {
                "com.whatsapp" -> "NotiReader_WA_Media"
                "com.whatsapp.w4b" -> "NotiReader_Business_Media"
                else -> "NotiReader_Other_Media"
            }

            val rootDir = java.io.File(appMediaDir, rootFolderName)
            if (!rootDir.exists()) rootDir.mkdirs()

            val typeDir = java.io.File(rootDir, matchedTypeValue)
            if (!typeDir.exists()) typeDir.mkdirs()

            val destFile = java.io.File(typeDir, newFileName)

            context.contentResolver.openInputStream(sourceUri)?.use { input ->
                destFile.outputStream().use { output ->
                    input.copyTo(output)
                    output.flush()
                }
            }

            Log.d("xyz", "MediaStore file copied to app storage: ${destFile.absolutePath}")
            return Uri.fromFile(destFile)

        } catch (e: Exception) {
            Log.e("xyz", "Error copying MediaStore file to app storage", e)
            null
        }
    }
}

package com.notireader.app.util

import android.content.Context
import android.content.Intent
import android.net.Uri
import android.provider.MediaStore
import android.util.Log
import kotlinx.coroutines.delay

object MediaStoreUtil {

    fun findMediaUsingMediaStore(
        context: Context,
        matchedTypeKey: String,
        timeStamp: Long?,
        sourcePackage: String
    ): Uri? {
        return try {
            val collectionUri = when (matchedTypeKey) {
                "Photo", "Sticker", "GIF" -> MediaStore.Images.Media.EXTERNAL_CONTENT_URI
                "Video" -> MediaStore.Video.Media.EXTERNAL_CONTENT_URI
                "Audio", "Voice message" -> MediaStore.Audio.Media.EXTERNAL_CONTENT_URI
                "Document" -> MediaStore.Files.getContentUri("external")
                else -> return null
            }

            val projection = arrayOf(
                MediaStore.MediaColumns._ID,
                MediaStore.MediaColumns.DISPLAY_NAME,
                MediaStore.MediaColumns.DATA,
                MediaStore.MediaColumns.DATE_ADDED,
                MediaStore.MediaColumns.SIZE
            )

            val notificationTimeInSeconds = (timeStamp ?: System.currentTimeMillis()) / 1000
            Log.d("xyz", "=== MediaStore Debug Info ===")
            Log.d("xyz", "Media type: $matchedTypeKey -> Collection: $collectionUri")
            Log.d("xyz", "Notification time: $notificationTimeInSeconds (${java.util.Date(timeStamp ?: 0)})")
            Log.d("xyz", "Source package: $sourcePackage")

            // Try multiple times with increasing search windows
            val maxRetries = 4
            val retryDelays = listOf(1000L, 3000L, 7000L, 15000L)
            val maxSearchWindows = listOf(30L, 60L, 120L, 300L)

            for (attempt in 0 until maxRetries) {
                Log.d("xyz", "=== MediaStore attempt ${attempt + 1}/$maxRetries ===")

                val maxSearchAfter = maxSearchWindows[attempt]

                val selection = "${MediaStore.MediaColumns.DATE_ADDED} > ? AND ${MediaStore.MediaColumns.DATE_ADDED} <= ?"
                val selectionArgs = arrayOf(
                    notificationTimeInSeconds.toString(),
                    (notificationTimeInSeconds + maxSearchAfter).toString()
                )
                val sortOrder = "${MediaStore.MediaColumns.DATE_ADDED} ASC"

                Log.d("xyz", "Search window: ${notificationTimeInSeconds} to ${notificationTimeInSeconds + maxSearchAfter} (${maxSearchAfter}s after)")

                var bestMatchUri: Uri? = null
                var bestMatchTimeDiff: Long = Long.MAX_VALUE
                var filesFound = 0
                var whatsappFilesFound = 0

                context.contentResolver.query(
                    collectionUri,
                    projection,
                    selection,
                    selectionArgs,
                    sortOrder
                )?.use { cursor ->
                    filesFound = cursor.count
                    Log.d("xyz", "Total files found in time window: $filesFound")

                    while (cursor.moveToNext()) {
                        val idColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns._ID)
                        val nameColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DISPLAY_NAME)
                        val dataColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DATA)
                        val dateColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DATE_ADDED)
                        val sizeColumn = cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.SIZE)

                        val fileId = cursor.getLong(idColumn)
                        val fileName = cursor.getString(nameColumn) ?: "Unknown"
                        val filePath = cursor.getString(dataColumn) ?: ""
                        val fileDate = cursor.getLong(dateColumn)
                        val fileSize = cursor.getLong(sizeColumn)

                        Log.d("xyz", "File: $fileName")
                        Log.d("xyz", "  Path: $filePath")
                        Log.d("xyz", "  Date: $fileDate (${java.util.Date(fileDate * 1000)})")
                        Log.d("xyz", "  Size: ${fileSize} bytes")
                        Log.d("xyz", "  Time diff: ${fileDate - notificationTimeInSeconds}s")

                        // Check if this file is from WhatsApp media directory
                        if (isWhatsAppMediaFile(filePath, sourcePackage)) {
                            whatsappFilesFound++
                            val timeDiff = fileDate - notificationTimeInSeconds
                            Log.d("xyz", "  ✅ WHATSAPP FILE FOUND! Time diff: ${timeDiff}s")

                            // Find the file with minimum positive time difference (closest after notification)
                            if (timeDiff > 0 && timeDiff < bestMatchTimeDiff) {
                                bestMatchTimeDiff = timeDiff
                                bestMatchUri = Uri.withAppendedPath(collectionUri, fileId.toString())
                                Log.d("xyz", "   NEW BEST MATCH: $fileName with time diff ${timeDiff}s")
                            }
                        } else {
                            Log.d("xyz", "  ❌ Not a WhatsApp file")
                        }
                    }
                }

                Log.d("xyz", "Summary for attempt ${attempt + 1}: Total files: $filesFound, WhatsApp files: $whatsappFilesFound")

                // If we found a match, return it
                if (bestMatchUri != null) {
                    Log.d("xyz", " MediaStore found best matching file with time diff: ${bestMatchTimeDiff}s")

                    // Try to take persistent permission if possible
                    try {
                        context.contentResolver.takePersistableUriPermission(
                            bestMatchUri,
                            Intent.FLAG_GRANT_READ_URI_PERMISSION
                        )
                        Log.d("xyz", "✅ Persistent permission granted")
                    } catch (e: SecurityException) {
                        Log.d("xyz", "⚠️ Could not take persistent permission: ${e.message}")
                    }

                    return bestMatchUri
                }

                // If not the last attempt, wait before retrying
                if (attempt < maxRetries - 1) {
                    Log.d("xyz", "No WhatsApp media found in attempt ${attempt + 1}, waiting ${retryDelays[attempt]}ms for download...")
                    Thread.sleep(retryDelays[attempt])
                }
            }

            Log.d("xyz", "❌ MediaStore query found no matching file after $maxRetries attempts")

            // DEBUG: Let's see what files exist in a wider time range for debugging
            Log.d("xyz", "=== DEBUG: Checking wider time range for any files ===")
            val debugSelection = "${MediaStore.MediaColumns.DATE_ADDED} >= ? AND ${MediaStore.MediaColumns.DATE_ADDED} <= ?"
            val debugSelectionArgs = arrayOf(
                (notificationTimeInSeconds - 300).toString(), // 5 minutes before
                (notificationTimeInSeconds + 300).toString()  // 5 minutes after
            )

            context.contentResolver.query(
                collectionUri,
                projection,
                debugSelection,
                debugSelectionArgs,
                "${MediaStore.MediaColumns.DATE_ADDED} DESC"
            )?.use { cursor ->
                Log.d("xyz", "DEBUG: Found ${cursor.count} files in 10-minute window around notification")
                var debugCount = 0
                while (cursor.moveToNext() && debugCount < 10) { // Show max 10 files
                    val fileName = cursor.getString(cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DISPLAY_NAME)) ?: "Unknown"
                    val filePath = cursor.getString(cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DATA)) ?: ""
                    val fileDate = cursor.getLong(cursor.getColumnIndexOrThrow(MediaStore.MediaColumns.DATE_ADDED))
                    val timeDiff = fileDate - notificationTimeInSeconds

                    Log.d("xyz", "DEBUG File ${debugCount + 1}: $fileName")
                    Log.d("xyz", "  Path: $filePath")
                    Log.d("xyz", "  Time diff: ${timeDiff}s")
                    Log.d("xyz", "  Is WhatsApp: ${isWhatsAppMediaFile(filePath, sourcePackage)}")
                    debugCount++
                }
            }

            null
        } catch (e: Exception) {
            Log.e("xyz", " Error searching MediaStore", e)
            null
        }
    }

    private fun isWhatsAppMediaFile(filePath: String?, sourcePackage: String): Boolean {
        if (filePath == null || filePath.isEmpty()) {
            Log.d("xyz", "    File path is null or empty")
            return false
        }

        Log.d("xyz", "    Checking if path belongs to WhatsApp: $filePath")

        val isWhatsAppFile = when (sourcePackage) {
            "com.whatsapp" -> {
                val checks = listOf(
                    filePath.contains("/WhatsApp/Media/", ignoreCase = true),
                    filePath.contains("/com.whatsapp/", ignoreCase = true),
                    filePath.contains("WhatsApp Images", ignoreCase = true),
                    filePath.contains("WhatsApp Video", ignoreCase = true),
                    filePath.contains("WhatsApp Audio", ignoreCase = true),
                    filePath.contains("WhatsApp Documents", ignoreCase = true),
                    filePath.contains("WhatsApp Voice Notes", ignoreCase = true),
                    filePath.contains("WhatsApp Stickers", ignoreCase = true),
                    filePath.contains("WhatsApp Animated Gifs", ignoreCase = true),
                    // Additional patterns for newer Android versions
                    filePath.contains("/Android/media/com.whatsapp/", ignoreCase = true),
                    filePath.contains("/storage/emulated/0/WhatsApp/", ignoreCase = true)
                )

                checks.forEachIndexed { index, check ->
                    if (check) {
                        Log.d("xyz", "    ✅ Matched WhatsApp pattern #${index + 1}")
                        return true
                    }
                }
                false
            }
            "com.whatsapp.w4b" -> {
                val checks = listOf(
                    filePath.contains("/WhatsApp Business/Media/", ignoreCase = true),
                    filePath.contains("/com.whatsapp.w4b/", ignoreCase = true),
                    filePath.contains("WhatsApp Business", ignoreCase = true),
                    // Additional patterns
                    filePath.contains("/Android/media/com.whatsapp.w4b/", ignoreCase = true),
                    filePath.contains("/storage/emulated/0/WhatsApp Business/", ignoreCase = true)
                )

                checks.forEachIndexed { index, check ->
                    if (check) {
                        Log.d("xyz", "    ✅ Matched WhatsApp Business pattern #${index + 1}")
                        return true
                    }
                }
                false
            }
            else -> false
        }

        if (!isWhatsAppFile) {
            Log.d("xyz", "    ❌ No WhatsApp patterns matched for $sourcePackage")
        }

        return isWhatsAppFile
    }

    fun copyMediaStoreFileToAppStorage(
        context: Context,
        sourceUri: Uri,
        matchedTypeValue: String,
        newFileName: String,
        sourcePackage: String
    ): Uri? {
        return try {
            val appMediaDir = context.getExternalFilesDir("media") ?: return null

            val rootFolderName = when (sourcePackage) {
                "com.whatsapp" -> "NotiReader_WA_Media"
                "com.whatsapp.w4b" -> "NotiReader_Business_Media"
                else -> "NotiReader_Other_Media"
            }

            val rootDir = java.io.File(appMediaDir, rootFolderName)
            if (!rootDir.exists()) rootDir.mkdirs()

            val typeDir = java.io.File(rootDir, matchedTypeValue)
            if (!typeDir.exists()) typeDir.mkdirs()

            val destFile = java.io.File(typeDir, newFileName)

            context.contentResolver.openInputStream(sourceUri)?.use { input ->
                destFile.outputStream().use { output ->
                    input.copyTo(output)
                    output.flush()
                }
            }

            Log.d("xyz", "MediaStore file copied to app storage: ${destFile.absolutePath}")
            return Uri.fromFile(destFile)

        } catch (e: Exception) {
            Log.e("xyz", "Error copying MediaStore file to app storage", e)
            null
        }
    }
}

// Add this method to MainActivity to check MediaStore permissions
private fun checkMediaStorePermissions() {
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
        val permissions = arrayOf(
            android.Manifest.permission.READ_MEDIA_IMAGES,
            android.Manifest.permission.READ_MEDIA_VIDEO,
            android.Manifest.permission.READ_MEDIA_AUDIO
        )

        val missingPermissions = permissions.filter {
            ContextCompat.checkSelfPermission(this, it) != PackageManager.PERMISSION_GRANTED
        }

        if (missingPermissions.isNotEmpty()) {
            Log.d("xyz", "Missing MediaStore permissions: $missingPermissions")
            ActivityCompat.requestPermissions(this, missingPermissions.toTypedArray(), 100)
        } else {
            Log.d("xyz", "All MediaStore permissions granted")
        }
    } else {
        // For older versions
        if (ContextCompat.checkSelfPermission(this, android.Manifest.permission.READ_EXTERNAL_STORAGE) 
            != PackageManager.PERMISSION_GRANTED) {
            Log.d("xyz", "Missing READ_EXTERNAL_STORAGE permission")
            ActivityCompat.requestPermissions(this, arrayOf(android.Manifest.permission.READ_EXTERNAL_STORAGE), 100)
        }
    }
}
